//! The descriptive attributes a map carries, which the crate keeps for the
//! caller and builds nothing from.
//!
//! `tests/data/metadata.xodr` and `metadata_bare.xodr` are generated by
//! `metadata.py`. The first gives every attribute, the second none, or an
//! unreadable one.

use xodr::{
    load_file_with_provenance, JunctionProvenance, LaneAdvisory, LaneType, Provenance, RoadNetwork,
};

fn full() -> (RoadNetwork, Provenance) {
    load_file_with_provenance("tests/data/metadata.xodr").unwrap()
}

fn bare() -> (RoadNetwork, Provenance) {
    load_file_with_provenance("tests/data/metadata_bare.xodr").unwrap()
}

#[test]
fn the_header_gives_every_attribute_it_has() {
    let (net, _) = full();
    let header = net.header();
    assert_eq!((header.rev_major, header.rev_minor), (Some(1), Some(9)));
    assert_eq!(header.name, "Caf\u{e9} & <Co> \"q\"");
    assert_eq!(header.version, "3.2");
    assert_eq!(header.date, "2026-01-01T00:00:00");
    assert_eq!(header.vendor, "Example Maps");
    assert_eq!(header.north, Some(120.5));
    assert_eq!(header.south, Some(-30.25));
    assert_eq!(header.east, Some(1050.0));
    assert_eq!(header.west, Some(-5.0));
}

#[test]
fn an_attribute_the_header_lacks_or_cannot_read_is_empty_or_none() {
    let (net, _) = bare();
    let header = net.header();
    assert_eq!((header.rev_major, header.rev_minor), (None, None));
    assert_eq!(header.north, None, "NaN is no number");
    assert_eq!(header.south, Some(-1.0));
    assert_eq!(header.east, Some(2.0));
    assert_eq!(header.west, Some(-3.0));
    assert_eq!(header.name, "");
    assert_eq!(header.version, "");
    assert_eq!(header.date, "");
    assert_eq!(header.vendor, "");
}

#[test]
fn a_map_with_no_header_has_an_empty_one() {
    let net = xodr::load_str(
        r#"<OpenDRIVE><road length="10" id="1" junction="-1">
          <planView><geometry s="0" x="0" y="0" hdg="0" length="10"><line/></geometry></planView>
          <lanes><laneSection s="0"><right><lane id="-1" type="driving"><width sOffset="0" a="3"/></lane></right></laneSection></lanes>
        </road></OpenDRIVE>"#,
    )
    .unwrap();
    assert_eq!(net.header(), &xodr::Header::default());
}

#[test]
fn a_road_keeps_its_name() {
    let (net, _) = full();
    let name = |id| net.road_by_od_id(id).unwrap().name().to_string();
    assert_eq!(name("1"), "Main Street");
    assert_eq!(name("11"), "");
    let (net, _) = bare();
    assert_eq!(net.road_by_od_id("1").unwrap().name(), "");
}

#[test]
fn a_junction_keeps_its_name() {
    let (_, prov) = full();
    assert_eq!(
        prov.junctions,
        [JunctionProvenance {
            od_id: "100".into(),
            name: "  Market Square  ".into()
        }]
    );
    let (_, prov) = bare();
    assert_eq!(prov.junctions[0].name, "");
}

#[cfg(feature = "serde")]
#[test]
fn the_header_and_the_road_names_survive_serde() {
    let (net, _) = full();
    let json = serde_json::to_string(&net).unwrap();
    let back: RoadNetwork = serde_json::from_str(&json).unwrap();
    assert_eq!(back.header(), net.header());
    assert_eq!(back.road_by_od_id("1").unwrap().name(), "Main Street");
    assert_eq!(back.objects(), net.objects());
    assert_eq!(back.signals(), net.signals());
    assert_eq!(back.header().name, "Caf\u{e9} & <Co> \"q\"");
    assert!(net.objects().iter().any(|o| o.invalidated));
    assert_eq!(back.road_countries(), net.road_countries());
    assert!(!back.road_countries().is_empty());
}

fn lane_of(prov: &Provenance, road: &str, od_id: i32) -> xodr::LaneId {
    prov.lanes
        .iter()
        .find(|p| p.road_id == road && p.od_id == od_id)
        .unwrap()
        .lane
}

#[test]
fn a_road_types_country_holds_along_the_lanes_until_the_next_type() {
    let (net, prov) = full();
    for od_id in [-1, 1] {
        let lane = lane_of(&prov, "1", od_id);
        assert_eq!(net.road_country_at(lane, 0.0), Some("DE"), "lane {od_id}");
        assert_eq!(net.road_country_at(lane, 10.0), Some("DE"), "lane {od_id}");
        assert_eq!(net.road_country_at(lane, 49.0), Some("DE"), "lane {od_id}");
        assert_eq!(net.road_country_at(lane, 50.0), Some("AT"), "lane {od_id}");
        assert_eq!(net.road_country_at(lane, 51.0), Some("AT"), "lane {od_id}");
        assert_eq!(net.road_country_at(lane, 79.0), Some("AT"), "lane {od_id}");
        assert_eq!(net.road_country_at(lane, 80.1), None, "lane {od_id}");
        assert_eq!(net.road_country_at(lane, 90.0), None, "lane {od_id}");
    }
    assert_eq!(net.road_country_at(lane_of(&prov, "11", -1), 5.0), None);
    assert_eq!(net.road_countries().len(), 4, "two lanes, two stretches");
}

#[test]
fn a_country_changes_nothing_about_the_road_type() {
    let (net, prov) = full();
    let lane = lane_of(&prov, "1", -1);
    assert_eq!(net.road_type_at(lane, 10.0), Some(xodr::RoadType::Town));
    assert_eq!(net.road_type_at(lane, 60.0), Some(xodr::RoadType::Rural));
    assert_eq!(net.road_type_at(lane, 90.0), Some(xodr::RoadType::Motorway));
}

#[test]
fn a_road_mark_keeps_its_material_and_its_types_name() {
    let (_, prov) = full();
    let mut marks: Vec<_> = prov
        .road_marks
        .iter()
        .filter(|m| m.road_id == "1")
        .map(|m| (m.od_lane_id, m.s, m.material.as_str(), m.type_name.as_str()))
        .collect();
    marks.sort_by(|a, b| (a.0, a.1).partial_cmp(&(b.0, b.1)).unwrap());
    assert_eq!(
        marks,
        [
            (-1, 0.0, "thermoplastic", "Edge Line"),
            (-1, 50.0, "cold-plastic", "Dashed"),
            (0, 0.0, "paint", ""),
            (1, 0.0, "", ""),
        ]
    );
}

#[test]
fn a_map_without_them_has_no_country_material_or_type_name() {
    let (net, prov) = bare();
    assert!(net.road_countries().is_empty());
    // scenariogeneration names the type of a dashed line "broken".
    assert_eq!(prov.road_marks.len(), 30);
    for m in &prov.road_marks {
        assert_eq!(m.material, "", "road {}", m.road_id);
        assert!(
            ["", "broken"].contains(&m.type_name.as_str()),
            "road {}",
            m.road_id
        );
    }
}

/// A lane's `advisory`, `dynamicLaneType`, `dynamicLaneDirection` and
/// `roadWorks`.
type Flags = (LaneAdvisory, bool, bool, bool);

/// `(section, lane id)` to the flags of road 2's lanes, in section then lane
/// order.
fn lane_flags(prov: &Provenance) -> Vec<((usize, i32), Flags)> {
    let mut found: Vec<_> = prov
        .lanes
        .iter()
        .filter(|p| p.road_id == "2")
        .map(|p| {
            (
                (p.section, p.od_id),
                (
                    p.advisory,
                    p.dynamic_lane_type,
                    p.dynamic_lane_direction,
                    p.road_works,
                ),
            )
        })
        .collect();
    found.sort_by_key(|(at, _)| *at);
    found
}

#[test]
fn a_lane_keeps_what_it_says_about_itself() {
    use LaneAdvisory::{Both, Inner, None as Unset, Outer};
    let (_, prov) = full();
    let flags = lane_flags(&prov);
    assert_eq!(flags.len(), 12, "six lanes in each of two sections");
    let expected = |section: usize, works: bool| {
        [
            ((section, -3), (Unset, false, false, false)),
            ((section, -2), (Unset, true, false, false)),
            ((section, -1), (Unset, false, false, works)),
            ((section, 1), (Inner, false, false, false)),
            ((section, 2), (Outer, false, false, false)),
            ((section, 3), (Both, true, true, false)),
        ]
    };
    let mut want: Vec<_> = expected(0, true).into_iter().collect();
    want.extend(expected(1, false));
    assert_eq!(flags, want);
}

#[test]
fn a_lane_with_none_of_it_has_the_defaults() {
    let (_, prov) = bare();
    assert_eq!(prov.lanes.len(), 22);
    for p in &prov.lanes {
        assert_eq!(p.advisory, LaneAdvisory::None, "lane {}", p.od_id);
        assert!(!p.dynamic_lane_type && !p.dynamic_lane_direction && !p.road_works);
    }
}

#[test]
fn the_center_lane_keeps_its_type_and_level_by_section() {
    let (_, prov) = full();
    let center = |road: &str| -> Vec<(usize, LaneType, bool)> {
        prov.center_lanes
            .iter()
            .filter(|c| c.road_id == road)
            .map(|c| (c.section, c.kind, c.level))
            .collect()
    };
    assert_eq!(center("1"), [(0, LaneType::None, false)]);
    assert_eq!(
        center("2"),
        [(0, LaneType::None, true), (1, LaneType::Driving, false)]
    );
    let tee: Vec<_> = prov
        .center_lanes
        .iter()
        .filter(|c| !["1", "2"].contains(&c.road_id.as_str()))
        .map(|c| (c.road_id.as_str(), c.section, c.kind, c.level))
        .collect();
    let none = LaneType::None;
    assert_eq!(
        tee,
        [
            ("11", 0, none, false),
            ("12", 0, none, false),
            ("13", 0, none, false),
            ("1000", 0, none, false),
            ("1001", 0, none, false),
        ]
    );
}

#[test]
fn a_section_with_no_center_lane_has_no_record() {
    let (_, prov) = xodr::load_str_with_provenance(
        r#"<OpenDRIVE><road length="10" id="1" junction="-1">
          <planView><geometry s="0" x="0" y="0" hdg="0" length="10"><line/></geometry></planView>
          <lanes><laneSection s="0"><right><lane id="-1" type="driving"><width sOffset="0" a="3"/></lane></right></laneSection></lanes>
        </road></OpenDRIVE>"#,
    )
    .unwrap();
    assert_eq!(prov.center_lanes, []);
}

/// Every object baked from `<object id>` `od_id`, with its provenance.
fn baked<'a>(
    net: &'a RoadNetwork,
    prov: &'a Provenance,
    od_id: &str,
) -> Vec<(&'a xodr::Object, &'a xodr::ObjectProvenance)> {
    prov.objects
        .iter()
        .filter(|p| p.od_id == od_id)
        .map(|p| (net.object(p.object).unwrap(), p))
        .collect()
}

#[test]
fn an_object_keeps_whether_it_is_invalidated_or_temporary() {
    let (net, prov) = full();
    let flags = |id| {
        let found = baked(&net, &prov, id);
        assert_eq!(found.len(), 1, "object {id}");
        (found[0].0.invalidated, found[0].0.temporary)
    };
    assert_eq!(flags("a1"), (true, true));
    assert_eq!(flags("a2"), (false, true));
    assert_eq!(flags("a3"), (false, false));
}

#[test]
fn a_material_keeps_the_colour_of_the_marks_on_it() {
    let (net, prov) = full();
    let materials = &baked(&net, &prov, "m1")[0].0.materials;
    let colours: Vec<_> = materials
        .iter()
        .map(|m| (m.surface.as_str(), m.road_mark_color.as_str()))
        .collect();
    assert_eq!(colours, [("asphalt", "yellow"), ("gravel", "")]);
}

#[test]
fn an_object_marking_keeps_its_weight_and_reads_anything_else_as_standard() {
    use xodr::RoadMarkWeight::{Bold, Standard};
    let (net, prov) = full();
    let marks = &baked(&net, &prov, "w")[0].0.markings;
    let weights: Vec<_> = marks.iter().map(|m| (m.side.as_str(), m.weight)).collect();
    assert_eq!(
        weights,
        [
            ("front", Bold),
            ("left", Standard),
            ("rear", Standard),
            ("right", Standard)
        ]
    );
}

#[test]
fn an_outline_keeps_its_fill_type_and_lane_type() {
    let (net, prov) = full();
    let outlines: Vec<_> = baked(&net, &prov, "o1")
        .into_iter()
        .map(|(_, p)| (p.fill_type.as_str(), p.outline_lane_type))
        .collect();
    assert_eq!(
        outlines,
        [
            ("grass", Some(LaneType::Sidewalk)),
            ("paint", Some(LaneType::Unknown)),
            ("", None),
        ],
        "the hole bakes into the outline round it, whose fill type stays"
    );
    let single = baked(&net, &prov, "o2");
    assert_eq!(single[0].1.fill_type, "gravel");
    assert_eq!(single[0].1.outline_lane_type, None);
}

#[test]
fn a_solid_has_no_fill_type() {
    let (net, prov) = full();
    let solid = &baked(&net, &prov, "a1")[0];
    assert_eq!(solid.1.fill_type, "");
    assert_eq!(solid.1.outline_lane_type, None);
}

fn signs(net: &RoadNetwork, prov: &Provenance) -> Vec<xodr::BoardSign> {
    let placed = prov.signals.iter().find(|p| p.od_id == "sg").unwrap();
    match &net.signals()[placed.signal.0].boards[..] {
        [xodr::SignalBoard::Static(signs)] => signs.clone(),
        other => panic!("one static board, got {other:?}"),
    }
}

#[test]
fn a_sign_on_a_board_keeps_every_attribute_it_has() {
    let (net, prov) = full();
    let signs = signs(&net, &prov);
    assert_eq!(signs.len(), 3);
    let one = &signs[0];
    assert_eq!((one.id.as_str(), one.name.as_str()), ("p1", "limit"));
    assert_eq!(one.country_revision, "2017");
    assert_eq!(one.orientation, xodr::Orientation::Positive);
    assert!(one.dynamic && one.invalidated && one.temporary);
    assert_eq!((one.h_offset, one.pitch, one.roll), (0.5, 0.25, -0.125));
    assert_eq!(one.length, Some(0.15));
    assert_eq!((one.width, one.height), (Some(0.6), Some(0.8)));
}

#[test]
fn a_sign_turns_wrap_and_its_orientation_is_its_own() {
    let (net, prov) = full();
    let two = &signs(&net, &prov)[1];
    let wrapped = 7.0 - 2.0 * std::f32::consts::PI;
    assert!((two.h_offset - wrapped).abs() < 1e-5, "{}", two.h_offset);
    assert_eq!(two.orientation, xodr::Orientation::Negative);
}

#[test]
fn a_sign_with_a_type_only_has_the_defaults() {
    let (net, prov) = full();
    let three = &signs(&net, &prov)[2];
    assert_eq!(three.kind, "101");
    assert_eq!(
        (three.id.as_str(), three.country_revision.as_str()),
        ("", "")
    );
    assert_eq!(three.orientation, xodr::Orientation::Both);
    assert!(!three.dynamic && !three.invalidated && !three.temporary);
    assert_eq!((three.h_offset, three.pitch, three.roll), (0.0, 0.0, 0.0));
    assert_eq!(three.length, None);
}

#[test]
fn a_lane_link_keeps_the_overlap_zone_it_gives() {
    let (_, prov) = full();
    let overlaps: Vec<_> = prov
        .lane_link_overlaps
        .iter()
        .map(|o| {
            (
                o.junction_id.as_str(),
                o.connection_id.as_str(),
                (o.incoming_road.as_str(), o.connecting_road.as_str()),
                (o.from, o.to),
                o.overlap_zone,
            )
        })
        .collect();
    assert_eq!(
        overlaps,
        [
            ("100", "0", ("11", "1000"), (-1, -1), 35.5),
            ("100", "0", ("11", "1000"), (1, -1), 7.5),
        ],
        "the link whose zone is unreadable has no record"
    );
    let (_, prov) = bare();
    assert_eq!(prov.lane_link_overlaps, []);
}

#[test]
fn a_direct_junction_names_the_road_it_links_as_the_connecting_one() {
    let (_, prov) = xodr::load_str_with_provenance(
        r#"<OpenDRIVE>
          <road length="10" id="1" junction="-1">
            <planView><geometry s="0" x="0" y="0" hdg="0" length="10"><line/></geometry></planView>
            <lanes><laneSection s="0"><right><lane id="-1" type="driving"><width sOffset="0" a="3"/></lane></right></laneSection></lanes>
          </road>
          <junction id="5" type="direct">
            <connection id="0" incomingRoad="1" linkedRoad="2" contactPoint="start">
              <laneLink from="-1" to="-2" overlapZone="12"/>
            </connection>
          </junction>
        </OpenDRIVE>"#,
    )
    .unwrap();
    let link = &prov.lane_link_overlaps[0];
    assert_eq!(
        (link.incoming_road.as_str(), link.connecting_road.as_str()),
        ("1", "2")
    );
    assert_eq!((link.from, link.to, link.overlap_zone), (-1, -2, 12.0));
}

#[test]
fn every_copy_of_a_repeated_outline_keeps_its_fill_type_and_lane_type() {
    let (net, prov) = full();
    let copies = baked(&net, &prov, "o3");
    assert_eq!(copies.len(), 3, "every 10 m for 20 m is 0, 10 and 20 m");
    for (_, p) in &copies {
        assert_eq!(p.fill_type, "grass");
        assert_eq!(p.outline_lane_type, Some(LaneType::Sidewalk));
    }
}

#[test]
fn a_boolean_that_is_not_true_false_or_a_digit_reads_as_false() {
    let (_, prov) = full();
    let lane = |section, od_id| {
        prov.lanes
            .iter()
            .find(|p| p.road_id == "2" && p.section == section && p.od_id == od_id)
            .unwrap()
    };
    assert!(lane(0, -1).road_works, "\"true\"");
    assert!(!lane(0, 2).road_works, "\"True\"");
    assert!(!lane(1, 2).road_works, "\"True\"");
}
